1	import Phaser from 'phaser';
2	import { SceneKey } from './keys';
3	import {
4	  GAME_WIDTH,
5	  GAME_HEIGHT,
6	  GROUND_TOP_Y,
7	  HERO_X,
8	  MAX_HP,
9	  TICK_DAMAGE,
10	  OBSTACLE_DAMAGE,
11	  TABLET_HEAL,
12	  TABLET_SCORE,
13	  SCORE_SURVIVAL_PER_S,
14	  LEVEL_LENGTH,
15	  SPAWN_MARGIN_PX,
16	  RECYCLE_MARGIN_PX,
17	  HERO_BODY_HEIGHT,
18	  PARALLAX_FACTOR_FAR,
19	  PARALLAX_FACTOR_NEAR,
20	  PARALLAX_FACTOR_GROUND,
21	  PARALLAX_FACTOR_GRASS,
22	  HIT_SHAKE_MS,
23	  HIT_SHAKE_INTENSITY,
24	  HIT_FLASH_MS,
25	  RESULTS_HANDOFF_DELAY_MS,
26	} from '../config/gameConfig';
27	import { KEYS } from '../config/assetManifest';
28	import { t } from '../i18n/strings';
29	import { track, type FinishGameParams } from '../analytics/track';
30	import { HeroDog } from '../entities/HeroDog';
31	import { FinishLine } from '../entities/FinishLine';
32	import { RunnerEntity } from '../entities/RunnerEntity';
33	import { DifficultyCurve } from '../systems/DifficultyCurve';
34	import { Spawner } from '../systems/Spawner';
35	
36	/**
37	 * Events emitted on `scene.events` for a future HUD / AudioManager to subscribe to
38	 * (Phase 4). The in-scene HUD here is a throwaway readout; Phase 4's Hud.ts can
39	 * listen to these instead of reaching into the scene. Payloads are primitives.
40	 */
41	export const GameEvents = {
42	  hp: 'hud:hp', // (hp: number)
43	  score: 'hud:score', // (score: number)
44	  progress: 'hud:progress', // (progress: number 0..1)
45	  armor: 'hud:armor', // ({ active: boolean, remainingMs: number })
46	  runStart: 'run:start', // ()
47	  runEnd: 'run:end', // (payload: FinishGameParams)
48	} as const;
49	
50	/** Render layering (presentation only). */
51	const Depth = {
52	  bgFar: 0,
53	  bgNear: 1,
54	  ground: 2,
55	  grass: 3,
56	  entity: 5,
57	  hero: 6,
58	  aura: 7,
59	  hud: 100,
60	} as const;
61	
62	/**
63	 * GameScene — the real, finite core run loop (spec §3, §5.2, §8.3).
64	 *
65	 * The hero is pinned at HERO_X and only moves vertically; the WORLD scrolls past
66	 * (parallax tileSprites + object-pooled entities driven by the DifficultyCurve).
67	 * Fires `start_game` on entry and `finish_game` on Victory (finish line) or Game
68	 * Over (0 HP), then hands the SAME {result, score, duration_s} payload to
69	 * ResultsScene — the exact handoff the placeholder used.
70	 */
71	export class GameScene extends Phaser.Scene {
72	  private hero!: HeroDog;
73	  private curve!: DifficultyCurve;
74	  private spawner!: Spawner;
75	  private finishLine!: FinishLine;
76	
77	  // Parallax layers.
78	  private bgFar!: Phaser.GameObjects.TileSprite;
79	  private bgNear!: Phaser.GameObjects.TileSprite;
80	  private groundTile!: Phaser.GameObjects.TileSprite;
81	  private fgGrass!: Phaser.GameObjects.TileSprite;
82	
83	  // HUD readout.
84	  private heartImages: Phaser.GameObjects.Image[] = [];
85	  private scoreText!: Phaser.GameObjects.Text;
86	  private progressFill!: Phaser.GameObjects.Rectangle;
87	
88	  // Run state.
89	  private distance = 0;
90	  private elapsedMs = 0;
91	  private tabletScore = 0;
92	  private score = 0;
93	  private finished = false;
94	  private finishSpawned = false;
95	
96	  // Change-tracking so HUD events only fire on transitions.
97	  private lastHp = MAX_HP;
98	  private lastScore = 0;
99	  private lastArmorActive = false;
100	
101	  private readonly spawnX = GAME_WIDTH + SPAWN_MARGIN_PX;
102	  private readonly recycleX = -RECYCLE_MARGIN_PX;
103	  /** Distance the hero covers while a right-edge spawn scrolls in to reach it. */
104	  private readonly approach = GAME_WIDTH + SPAWN_MARGIN_PX - HERO_X;
105	
106	  constructor() {
107	    super({ key: SceneKey.Game });
108	  }
109	
110	  create(): void {
111	    this.resetState();
112	    this.buildParallax();
113	    this.buildGroundAndHero();
114	    this.buildSystems();
115	    this.buildFinishLine();
116	    this.registerCollisions();
117	    this.buildHud();
118	    this.buildInput();
119	
120	    // A round has begun (spec §5.2).
121	    track('start_game');
122	    this.events.emit(GameEvents.runStart);
123	
124	    this.events.once(Phaser.Scenes.Events.SHUTDOWN, this.cleanup, this);
125	  }
126	
127	  // ── Public read hooks (Phase 4 HUD/audio can poll these) ───────────────────
128	  get liveHp(): number {
129	    return this.hero.hp;
130	  }
131	  get liveScore(): number {
132	    return this.score;
133	  }
134	  get liveProgress(): number {
135	    return this.curve.progress(this.distance);
136	  }
137	
138	  // ── Build steps ─────────────────────────────────────────────────────────────
139	  private resetState(): void {
140	    this.distance = 0;
141	    this.elapsedMs = 0;
142	    this.tabletScore = 0;
143	    this.score = 0;
144	    this.finished = false;
145	    this.finishSpawned = false;
146	    this.lastHp = MAX_HP;
147	    this.lastScore = 0;
148	    this.lastArmorActive = false;
149	    this.heartImages = [];
150	  }
151	
152	  private buildParallax(): void {
153	    const cx = GAME_WIDTH / 2;
154	    this.bgFar = this.add
155	      .tileSprite(cx, GAME_HEIGHT / 2, GAME_WIDTH, GAME_HEIGHT, KEYS.park_bg_far)
156	      .setDepth(Depth.bgFar);
157	    this.bgNear = this.add
158	      .tileSprite(cx, GROUND_TOP_Y, GAME_WIDTH, 360, KEYS.park_bg_near)
159	      .setOrigin(0.5, 1)
160	      .setDepth(Depth.bgNear);
161	    this.groundTile = this.add
162	      .tileSprite(cx, GROUND_TOP_Y, GAME_WIDTH, GAME_HEIGHT - GROUND_TOP_Y, KEYS.ground_tile)
163	      .setOrigin(0.5, 0)
164	      .setDepth(Depth.ground);
165	    this.fgGrass = this.add
166	      .tileSprite(cx, GAME_HEIGHT, GAME_WIDTH, 140, KEYS.park_fg_grass)
167	      .setOrigin(0.5, 1)
168	      .setDepth(Depth.grass);
169	  }
170	
171	  private buildGroundAndHero(): void {
172	    this.hero = new HeroDog(this, HERO_X, GROUND_TOP_Y);
173	    this.hero.setDepth(Depth.hero);
174	    this.hero.auraSprite.setDepth(Depth.aura);
175	
176	    // Invisible static floor so the hero's jump arc lands cleanly.
177	    const ground = this.add
178	      .rectangle(GAME_WIDTH / 2, GROUND_TOP_Y, GAME_WIDTH, GAME_HEIGHT - GROUND_TOP_Y, 0x000000, 0)
179	      .setOrigin(0.5, 0);
180	    this.physics.add.existing(ground, true);
181	    this.physics.add.collider(this.hero, ground);
182	  }
183	
184	  private buildSystems(): void {
185	    this.curve = new DifficultyCurve();
186	    this.spawner = new Spawner(this, this.curve, GROUND_TOP_Y, this.spawnX, this.recycleX);
187	  }
188	
189	  private buildFinishLine(): void {
190	    this.finishLine = new FinishLine(this);
191	    this.finishLine.setDepth(Depth.entity);
192	    this.add.existing(this.finishLine);
193	    this.physics.add.existing(this.finishLine);
194	    this.finishLine.recycle(); // hidden until it's queued near LEVEL_LENGTH
195	  }
196	
197	  private registerCollisions(): void {
198	    // Ticks: damage; when armored, the tick is CONSUMED for a powerful feel (§3.7).
199	    this.physics.add.overlap(
200	      this.hero,
201	      this.spawner.tickPool,
202	      (_h, obj) => this.onTick(obj as RunnerEntity),
203	      undefined,
204	      this,
205	    );
206	    // Bush/puddle: damage; ignored (not consumed) while invulnerable.
207	    this.physics.add.overlap(
208	      this.hero,
209	      this.spawner.obstaclePools,
210	      (_h, obj) => this.onObstacle(obj as RunnerEntity),
211	      undefined,
212	      this,
213	    );
214	    // Tablet: +score & +1 HP (capped).
215	    this.physics.add.overlap(
216	      this.hero,
217	      this.spawner.tabletPool,
218	      (_h, obj) => this.onTablet(obj as RunnerEntity),
219	      undefined,
220	      this,
221	    );
222	    // Armor: activate timed invulnerability + burst VFX.
223	    this.physics.add.overlap(
224	      this.hero,
225	      this.spawner.armorPool,
226	      (_h, obj) => this.onArmor(obj as RunnerEntity),
227	      undefined,
228	      this,
229	    );
230	    // Finish line: Victory.
231	    this.physics.add.overlap(this.hero, this.finishLine, () => this.endRun('win'), undefined, this);
232	  }
233	
234	  private buildHud(): void {
235	    // Level-progress bar (frame asset + a dynamic fill inset within it).
236	    const barY = 16;
237	    const barW = 1180; // == ui_progress_bar asset width
238	    const barLeft = GAME_WIDTH / 2 - barW / 2;
239	    this.add.image(GAME_WIDTH / 2, barY, KEYS.ui_progress_bar).setDepth(Depth.hud);
240	    this.progressFill = this.add
241	      .rectangle(barLeft + 2, barY, barW - 4, 8, 0x6cc04a)
242	      .setOrigin(0, 0.5)
243	      .setDepth(Depth.hud);
244	    this.progressFill.scaleX = 0;
245	
246	    // Score row (top-left).
247	    const rowY = 58;
248	    this.add.image(38, rowY, KEYS.ui_score_icon).setDepth(Depth.hud);
249	    this.scoreText = this.add
250	      .text(68, rowY, `${t('hud_score')}: 0`, {
251	        fontFamily: 'system-ui, sans-serif',
252	        fontSize: '26px',
253	        fontStyle: 'bold',
254	        color: '#20272e',
255	      })
256	      .setOrigin(0, 0.5)
257	      .setDepth(Depth.hud);
258	
259	    // Hearts (below the score row).
260	    for (let i = 0; i < MAX_HP; i++) {
261	      this.heartImages.push(this.add.image(42 + i * 44, 100, KEYS.ui_heart_full).setDepth(Depth.hud));
262	    }
263	  }
264	
265	  private buildInput(): void {
266	    // The WHOLE canvas is the jump zone (spec §3.2 / §10.4). Auto-run is always on.
267	    this.input.on(Phaser.Input.Events.POINTER_DOWN, () => this.hero.jump());
268	    this.input.keyboard
269	      ?.addKey(Phaser.Input.Keyboard.KeyCodes.SPACE)
270	      .on('down', () => this.hero.jump());
271	  }
272	
273	  // ── Per-frame loop ────────────────────────────────────────────────────────────
274	  override update(time: number, delta: number): void {
275	    if (this.finished) return;
276	
277	    const dt = delta / 1000;
278	    this.elapsedMs += delta;
279	
280	    const progress = this.curve.progress(this.distance);
281	    const worldSpeed = this.curve.speed(progress);
282	    this.distance += worldSpeed * dt;
283	
284	    this.scrollParallax(worldSpeed, dt);
285	    this.spawner.update(this.distance, worldSpeed, progress);
286	    this.updateFinishLine(worldSpeed);
287	
288	    this.hero.tick(time);
289	    this.updateScore();
290	    this.updateHud(progress);
291	    this.emitArmor(time);
292	
293	    // Deterministic Victory: the finish line has reached the hero.
294	    if (this.finishSpawned && this.finishLine.active && this.finishLine.x <= HERO_X) {
295	      this.endRun('win');
296	    }
297	  }
298	
299	  private scrollParallax(worldSpeed: number, dt: number): void {
300	    this.bgFar.tilePositionX += worldSpeed * PARALLAX_FACTOR_FAR * dt;
301	    this.bgNear.tilePositionX += worldSpeed * PARALLAX_FACTOR_NEAR * dt;
302	    this.groundTile.tilePositionX += worldSpeed * PARALLAX_FACTOR_GROUND * dt;
303	    this.fgGrass.tilePositionX += worldSpeed * PARALLAX_FACTOR_GRASS * dt;
304	  }
305	
306	  private updateFinishLine(worldSpeed: number): void {
307	    if (!this.finishSpawned) {
308	      if (this.distance >= LEVEL_LENGTH - this.approach) {
309	        this.finishLine.spawn(this.spawnX, GROUND_TOP_Y);
310	        this.finishSpawned = true;
311	        this.spawner.stopSpawning(); // nothing spawns past the finish (§3.9)
312	      }
313	      return;
314	    }
315	    if (this.finishLine.active) this.finishLine.setVelocityX(-worldSpeed);
316	  }
317	
318	  private updateScore(): void {
319	    const survival = Math.floor((this.elapsedMs / 1000) * SCORE_SURVIVAL_PER_S);
320	    this.score = this.tabletScore + survival;
321	    if (this.score !== this.lastScore) {
322	      this.scoreText.setText(`${t('hud_score')}: ${this.score}`);
323	      this.events.emit(GameEvents.score, this.score);
324	      this.lastScore = this.score;
325	    }
326	  }
327	
328	  private updateHud(progress: number): void {
329	    this.progressFill.scaleX = progress;
330	    this.events.emit(GameEvents.progress, progress);
331	    if (this.hero.hp !== this.lastHp) this.refreshHearts();
332	  }
333	
334	  private refreshHearts(): void {
335	    const hp = this.hero.hp;
336	    this.heartImages.forEach((img, i) => {
337	      img.setTexture(i < hp ? KEYS.ui_heart_full : KEYS.ui_heart_empty);
338	    });
339	    this.events.emit(GameEvents.hp, hp);
340	    this.lastHp = hp;
341	  }
342	
343	  private emitArmor(time: number): void {
344	    const active = this.hero.isArmored(time);
345	    const remainingMs = this.hero.armorRemaining(time);
346	    if (active !== this.lastArmorActive) {
347	      this.events.emit(GameEvents.armor, { active, remainingMs });
348	      this.lastArmorActive = active;
349	    }
350	  }
351	
352	  // ── Collision handlers ─────────────────────────────────────────────────────────
353	  private onTick(tick: RunnerEntity): void {
354	    if (this.finished || !tick.active) return;
355	    const time = this.time.now;
356	    if (this.hero.isArmored(time)) {
357	      tick.recycle(); // consumed by the shield — feels powerful (§3.7)
358	      return;
359	    }
360	    if (this.hero.isInvulnerable(time)) return; // mid i-frame — ignore, don't consume
361	    if (this.hero.takeHit(time, TICK_DAMAGE)) {
362	      tick.recycle();
363	      this.onHeroDamaged();
364	    }
365	  }
366	
367	  private onObstacle(obstacle: RunnerEntity): void {
368	    if (this.finished || !obstacle.active) return;
369	    const time = this.time.now;
370	    if (this.hero.isInvulnerable(time)) return; // armored or i-frame → no damage
371	    if (this.hero.takeHit(time, OBSTACLE_DAMAGE)) {
372	      this.onHeroDamaged(); // the dog bumps it; obstacle keeps scrolling
373	    }
374	  }
375	
376	  private onTablet(tablet: RunnerEntity): void {
377	    if (this.finished || !tablet.active) return;
378	    tablet.recycle();
379	    this.tabletScore += TABLET_SCORE;
380	    this.hero.heal(TABLET_HEAL);
381	    this.refreshHearts();
382	  }
383	
384	  private onArmor(armor: RunnerEntity): void {
385	    if (this.finished || !armor.active) return;
386	    armor.recycle();
387	    this.hero.activateArmor(this.time.now);
388	    this.spawnArmorBurst();
389	  }
390	
391	  private onHeroDamaged(): void {
392	    this.cameras.main.shake(HIT_SHAKE_MS, HIT_SHAKE_INTENSITY);
393	    this.cameras.main.flash(HIT_FLASH_MS, 200, 60, 60);
394	    this.refreshHearts();
395	    if (this.hero.hp <= 0) this.endRun('lose');
396	  }
397	
398	  /** One-shot pickup burst VFX (rare — not pooled; tween-then-destroy). */
399	  private spawnArmorBurst(): void {
400	    const burst = this.add
401	      .image(this.hero.x, this.hero.y - HERO_BODY_HEIGHT * 0.55, KEYS.vfx_armor_burst)
402	      .setDepth(Depth.aura);
403	    this.tweens.add({
404	      targets: burst,
405	      scale: { from: 0.5, to: 1.4 },
406	      alpha: { from: 1, to: 0 },
407	      duration: 380,
408	      ease: 'Quad.out',
409	      onComplete: () => burst.destroy(),
410	    });
411	  }
412	
413	  // ── Termination ────────────────────────────────────────────────────────────────
414	  private endRun(result: 'win' | 'lose'): void {
415	    if (this.finished) return;
416	    this.finished = true;
417	
418	    if (result === 'win') this.hero.victory();
419	    else this.hero.defeat();
420	
421	    this.spawner.freeze();
422	    if (this.finishLine.active) this.finishLine.setVelocityX(0);
423	
424	    const payload: FinishGameParams = {
425	      result,
426	      score: this.score,
427	      duration_s: Math.round(this.elapsedMs / 1000),
428	    };
429	    track('finish_game', payload);
430	    this.events.emit(GameEvents.runEnd, payload);
431	
432	    // Let the win/lose pose read, then hand off with the EXACT placeholder payload.
433	    this.time.delayedCall(RESULTS_HANDOFF_DELAY_MS, () => {
434	      this.scene.start(SceneKey.Results, payload);
435	    });
436	  }
437	
438	  private cleanup(): void {
439	    // Tweens/timers/display objects are scene-scoped and auto-destroyed; destroy the
440	    // pools explicitly so re-entering Game (play again) never leaks or double-fires.
441	    this.spawner.destroy();
442	    this.heartImages = [];
443	  }
444	}
