58	    scene: Phaser.Scene,
59	    private readonly curve: DifficultyCurve,
60	    private readonly groundY: number,
61	    private readonly spawnX: number,
62	    private readonly recycleX: number,
63	  ) {
64	    const mk = (classType: Function, maxSize: number): Phaser.Physics.Arcade.Group =>
