92	   * recycle every active entity. `distance` is world units travelled so far.
93	   */
94	  update(distance: number, worldSpeed: number, progress: number): void {
95	    if (this.spawningEnabled) {
96	      while (distance >= this.nextHazardDistance) {
97	        this.spawnHazard();
98	        this.nextHazardDistance += this.curve.hazardSpacing(progress);
99	      }
100	      while (distance >= this.nextTabletDistance) {
101	        this.spawnTablet();
102	        this.nextTabletDistance += this.curve.tabletSpacing(progress);
103	      }
104	      while (this.armorQueue.length > 0 && distance >= this.armorQueue[0]!) {
105	        this.armorQueue.shift();
106	        this.spawnArmor();
107	      }
108	    }
109	
110	    this.scrollAndRecycle(worldSpeed);
111	  }
112	
113	  /** Stop scheduling NEW spawns (called once the finish line is queued, §3.9). */
114	  stopSpawning(): void {
115	    this.spawningEnabled = false;
116	  }
117	
118	  /** Freeze every live entity in place (zero horizontal velocity) — used on run end. */
119	  freeze(): void {
120	    for (const pool of this.allPools) {
121	      for (const child of pool.getChildren()) {
122	        const e = child as RunnerEntity;
123	        if (e.active) e.setVelocityX(0);
124	      }
125	    }
126	  }
127	
128	  /** Recycle everything currently live (e.g. on a clean restart). */
129	  recycleAll(): void {
130	    for (const pool of this.allPools) {
131	      for (const child of pool.getChildren()) {
132	        (child as RunnerEntity).recycle();
133	      }
134	    }
135	  }
136	
137	  destroy(): void {
138	    for (const pool of this.allPools) pool.destroy(true);
139	  }
140	
141	  // ── Spawning ─────────────────────────────────────────────────────────────────
142	  private spawnHazard(): void {
143	    const pool = this.pickHazardPool();
144	    const entity = pool.get(this.spawnX, this.groundY) as RunnerEntity | null;
145	    if (!entity) return; // pool exhausted — skip (sized so this shouldn't happen)
146	    entity.spawn(this.spawnX, this.groundY); // ground entities: feet on the ground line
147	  }
148	
149	  private spawnTablet(): void {
150	    const y = this.hoverY();
151	    const entity = this.tabletPool.get(this.spawnX, y) as RunnerEntity | null;
152	    if (!entity) return;
153	    entity.spawn(this.spawnX, y);
154	  }
155	
156	  private spawnArmor(): void {
157	    const y = this.hoverY();
158	    const entity = this.armorPool.get(this.spawnX, y) as RunnerEntity | null;
159	    if (!entity) return;
160	    entity.spawn(this.spawnX, y);
161	  }
162	
163	  /** A hover height above the ground that always requires a jump to reach. */
164	  private hoverY(): number {
165	    return this.groundY - COLLECTIBLE_HOVER_PX - Phaser.Math.Between(0, COLLECTIBLE_HOVER_JITTER_PX);
166	  }
167	
168	  private pickHazardPool(): Phaser.Physics.Arcade.Group {
169	    const roll = Phaser.Math.Between(1, this.hazardWeightTotal);
170	    let acc = 0;
171	    for (const h of this.hazardTable) {
172	      acc += h.weight;
173	      if (roll <= acc) return h.group;
174	    }
175	    return this.tickPool; // unreachable; satisfies the type checker
176	  }
177	
178	  private buildArmorSchedule(): void {
179	    const n: number = ARMOR_SPAWNS_PER_LEVEL; // widen from the literal type for the i/(n-1) math
180	    for (let i = 0; i < n; i++) {
181	      const frac = n === 1 ? 0.5 : Phaser.Math.Linear(0.25, 0.85, i / (n - 1));
182	      this.armorQueue.push(frac * LEVEL_LENGTH);
183	    }
184	  }
185	
186	  // ── Motion / recycling ───────────────────────────────────────────────────────
187	  private scrollAndRecycle(worldSpeed: number): void {
188	    for (const pool of this.allPools) {
189	      for (const child of pool.getChildren()) {
190	        const e = child as RunnerEntity;
191	        if (!e.active) continue;
192	        e.setVelocityX(-worldSpeed);
193	        if (e.isOffscreenLeft(this.recycleX)) e.recycle();
194	      }
195	    }
196	  }
197	}
