1	import Phaser from 'phaser';
2	import { KEYS } from '../config/assetManifest';
3	import {
4	  GRAVITY_Y,
5	  JUMP_VELOCITY_Y,
6	  MAX_HP,
7	  START_HP,
8	  INVULN_MS,
9	  INVULN_BLINK_MS,
10	  ARMOR_DURATION_MS,
11	  ARMOR_EXPIRY_TELL_MS,
12	  ARMOR_AURA_BLINK_MS,
13	  HERO_BODY_WIDTH,
14	  HERO_BODY_HEIGHT,
15	  HERO_RUN_TILT_DEG,
16	  HERO_RUN_TILT_MS,
17	  HERO_JUMP_STRETCH,
18	  HERO_JUMP_STRETCH_MS,
19	  HERO_LAND_SQUASH,
20	  HERO_LAND_SQUASH_MS,
21	  HERO_HIT_POSE_MS,
22	  HIT_FLASH_MS,
23	  HERO_VICTORY_HOP_VELOCITY,
24	} from '../config/gameConfig';
25	
26	/** Visual/logic state of the hero (spec §4.1 — the five animation states). */
27	export type HeroState = 'run' | 'jump' | 'hit' | 'victory' | 'defeat';
28	
29	/**
30	 * HeroDog — the player avatar (spec §3.3, §3.4, §3.7).
31	 *
32	 * An Arcade-physics sprite pinned at a fixed screen X while the world scrolls past
33	 * (the Spawner/parallax move; the dog only moves vertically). Owns:
34	 *  - a run → jump → hit → victory/defeat state machine (single SVG per state);
35	 *  - HP with a post-hit invulnerability (i-frame) window so one contact can't
36	 *    drain multiple hearts (§3.4);
37	 *  - the Armor power-up: timed total invulnerability with a `dog_armored` art swap,
38	 *    a persistent aura, and an expiry blink tell (§3.7 / §4.4).
39	 *
40	 * Animation is done with tweens on body-safe channels: run uses an ANGLE tilt
41	 * (Arcade AABBs ignore rotation, so the hitbox never wobbles); jump squash/stretch
42	 * scales briefly only at takeoff/landing (never mid-air where collectibles are
43	 * grabbed); i-frames blink ALPHA. The scene drives per-frame work via `tick()`.
44	 */
45	export class HeroDog extends Phaser.Physics.Arcade.Sprite {
46	  hp = START_HP;
47	
48	  private heroState: HeroState = 'run';
49	  private grounded = true;
50	  private armorUntil = 0;
51	  private invulnUntil = 0;
52	
53	  /** Persistent shield aura shown while armored; follows the dog in `tick()`. */
54	  private readonly aura: Phaser.GameObjects.Image;
55	
56	  private runTilt?: Phaser.Tweens.Tween | undefined;
57	  private blink?: Phaser.Tweens.Tween | undefined;
58	  private hitPoseTimer?: Phaser.Time.TimerEvent;
59	  private flashTimer?: Phaser.Time.TimerEvent;
60	
61	  constructor(scene: Phaser.Scene, x: number, y: number) {
62	    super(scene, x, y, KEYS.dog_run);
63	    this.setOrigin(0.5, 1); // feet rest on the ground line at `y`
64	    scene.add.existing(this);
65	    scene.physics.add.existing(this);
66	
67	    const body = this.body as Phaser.Physics.Arcade.Body;
68	    body.setGravityY(GRAVITY_Y);
69	    body.setVelocity(0, 0);
70	    this.applyBody();
71	
72	    // Aura sits just above the hero; created hidden, shown on armor pickup.
73	    this.aura = scene.add.image(x, y, KEYS.vfx_armor_aura).setOrigin(0.5, 0.5);
74	    this.aura.setVisible(false).setActive(false);
75	
76	    this.enterRun();
77	  }
78	
79	  // ── Public state queries (also power the Phase-4 HUD hooks) ────────────────
80	  // NB: named `currentState` (not `state`) — Phaser.GameObjects.Sprite already
81	  // owns a `state` property, which a getter cannot legally override.
82	  get currentState(): HeroState {
83	    return this.heroState;
84	  }
85	
86	  get isAlive(): boolean {
87	    return this.heroState !== 'defeat' && this.heroState !== 'victory';
88	  }
89	
90	  isArmored(time: number): boolean {
91	    return time < this.armorUntil;
92	  }
93	
94	  /** True while EITHER armor or the post-hit i-frame window is active. */
95	  isInvulnerable(time: number): boolean {
96	    return time < this.armorUntil || time < this.invulnUntil;
97	  }
98	
99	  /** Milliseconds of armor remaining (0 if not armored) — for the HUD/audio tell. */
100	  armorRemaining(time: number): number {
101	    return Math.max(0, this.armorUntil - time);
102	  }
103	
104	  /** The shared aura game object (so the scene can order its depth once). */
105	  get auraSprite(): Phaser.GameObjects.Image {
106	    return this.aura;
107	  }
108	
109	  // ── Input ──────────────────────────────────────────────────────────────────
110	  /** Edge-triggered jump: fires only when grounded & alive; ignored airborne. */
111	  jump(): void {
112	    if (!this.isAlive || !this.grounded) return;
113	    const body = this.body as Phaser.Physics.Arcade.Body;
114	    body.setVelocityY(JUMP_VELOCITY_Y);
115	    this.grounded = false;
116	    this.enterJump();
117	  }
118	
119	  // ── Damage / heal / armor ───────────────────────────────────────────────────
120	  /**
121	   * Apply `amount` damage. Returns true only if HP was actually removed (false
122	   * when invulnerable) so the caller knows whether to consume the hazard / react.
123	   * i-frames are what stop a single lingering contact from draining several HP.
124	   */
125	  takeHit(time: number, amount: number): boolean {
126	    if (!this.isAlive || this.isInvulnerable(time)) return false;
127	
128	    this.hp = Math.max(0, this.hp - amount);
129	    this.invulnUntil = time + INVULN_MS;
130	    this.enterHit();
131	    this.startBlink();
132	    return true;
133	  }
134	
135	  /** Heal by `amount`, capped at the 3-heart max (spec §3.4). */
136	  heal(amount: number): void {
137	    this.hp = Math.min(MAX_HP, this.hp + amount);
138	  }
139	
140	  /** Activate the Armor power-up: timed total invulnerability + art swap (§3.7). */
141	  activateArmor(time: number): void {
142	    this.armorUntil = time + ARMOR_DURATION_MS;
143	    this.aura.setVisible(true).setActive(true).setAlpha(1);
144	    // Post-hit blink is redundant under armor — clear it for a clean aura read.
145	    this.stopBlink();
146	    if (this.heroState === 'run') this.setHeroTexture(KEYS.dog_armored);
147	  }
148	
149	  // ── Terminal poses ───────────────────────────────────────────────────────────
150	  victory(): void {
151	    if (!this.isAlive) return;
152	    this.enterEnd('victory');
153	    const body = this.body as Phaser.Physics.Arcade.Body;
154	    // Re-enable a brief hop for celebration, then let it settle.
155	    body.setVelocity(0, HERO_VICTORY_HOP_VELOCITY);
156	    this.scene.tweens.add({
157	      targets: this,
158	      scaleX: 1.06,
159	      scaleY: 0.94,
160	      duration: 160,
161	      yoyo: true,
162	      ease: 'Quad.out',
163	    });
164	  }
165	
166	  defeat(): void {
167	    if (!this.isAlive) return;
168	    this.enterEnd('defeat');
169	    this.scene.tweens.add({
170	      targets: this,
171	      angle: -8,
172	      duration: 220,
173	      ease: 'Quad.out',
174	    });
175	  }
176	
177	  // ── Per-frame update (called by the scene) ──────────────────────────────────
178	  tick(time: number): void {
179	    const body = this.body as Phaser.Physics.Arcade.Body | null;
180	
181	    if (this.heroState === 'victory' || this.heroState === 'defeat') {
182	      this.aura.setVisible(false);
183	      return;
184	    }
185	
186	    // Landing detection: a jump that has touched the floor returns to run.
187	    if (body) {
188	      const onFloor = body.onFloor();
189	      if (onFloor && !this.grounded && this.heroState === 'jump') {
190	        this.grounded = true;
191	        this.onLanded();
192	      }
193	      this.grounded = onFloor;
194	    }
195	
196	    // Armor lifetime + expiry tell.
197	    if (this.armorUntil > 0) {
198	      if (time >= this.armorUntil) {
199	        this.deactivateArmor();
200	      } else {
201	        this.updateAura(time);
202	      }
203	    }
204	
205	    // i-frame expiry (independent of armor).
206	    if (this.invulnUntil > 0 && time >= this.invulnUntil) {
207	      this.stopBlink();
208	    }
209	  }
210	
211	  // ── State entry helpers ──────────────────────────────────────────────────────
212	  private enterRun(): void {
213	    this.heroState = 'run';
214	    this.setHeroTexture(this.isArmored(this.scene.time.now) ? KEYS.dog_armored : KEYS.dog_run);
215	    this.setScale(1);
216	    this.startRunTilt();
217	  }
218	
