1	import Phaser from 'phaser';
2	import {
3	  LEVEL_LENGTH,
4	  SCROLL_SPEED_START,
5	  SCROLL_SPEED_MAX,
6	  HAZARD_SPACING_START,
7	  HAZARD_SPACING_END,
8	  TABLET_SPACING_START,
9	  LATE_GENEROSITY_FACTOR,
10	} from '../config/gameConfig';
