12	/**
13	 * DifficultyCurve — the authored ramp over the finite level (spec §3.8).
14	 *
15	 * Pure, stateless functions of `progress` (distance / LEVEL_LENGTH, clamped to
16	 * [0,1]) so the ramp is repeatable and tunable entirely from gameConfig:
17	 *  - world SPEED rises start → max;
18	 *  - hazard SPACING tightens start → end (always jump-clearable, §3.2);
19	 *  - collectible GENEROSITY tapers in the final quarter to raise late tension,
20	 *    which WIDENS tablet spacing near the finish.
21	 */
22	export class DifficultyCurve {
23	  /** Fraction of the level completed, from distance travelled. */
24	  progress(distance: number): number {
25	    return Phaser.Math.Clamp(distance / LEVEL_LENGTH, 0, 1);
26	  }
27	
28	  /** World scroll speed (px/s) at this progress. */
29	  speed(progress: number): number {
30	    return Phaser.Math.Linear(SCROLL_SPEED_START, SCROLL_SPEED_MAX, progress);
31	  }
32	
33	  /** Center-to-center world spacing (== on-screen px) between consecutive hazards. */
34	  hazardSpacing(progress: number): number {
35	    return Phaser.Math.Linear(HAZARD_SPACING_START, HAZARD_SPACING_END, progress);
36	  }
37	
38	  /**
39	   * Collectible generosity multiplier: 1.0 until the final quarter, then eases to
40	   * LATE_GENEROSITY_FACTOR by the finish (fewer freebies near the end).
41	   */
42	  generosity(progress: number): number {
43	    if (progress <= 0.75) return 1;
44	    const tail = (progress - 0.75) / 0.25; // 0 → 1 across the last quarter
45	    return Phaser.Math.Linear(1, LATE_GENEROSITY_FACTOR, tail);
46	  }
47	
48	  /** World spacing between tablets — widens as generosity tapers late-game. */
49	  tabletSpacing(progress: number): number {
50	    return TABLET_SPACING_START / this.generosity(progress);
51	  }
52	}
